// `pnpm dev` runs `netlify dev`, which applies dist/_headers (the production CSP generated by
// scripts/build-csp.mjs) to the Astro dev server. That CSP only allows the hashes of the
// *production* inline blocks, so it blocks Astro dev's own inline styles/scripts and the page
// renders unstyled. Dropping the file before dev starts avoids that; `build:all` recreates it.
import { rmSync } from 'node:fs';

rmSync('dist/_headers', { force: true });
